# Check the 7s rectangle gap
print("7s rectangle at rows 2-4, cols 9-11")
rmin, rmax = 2, 4
cmin, cmax = 9, 11
print(f"\nCell by cell:")
for r in range(rmin, rmax+1):
    for c in range(cmin, cmax+1):
        val = grid[r][c]
        marker = "✓" if grid[r][c] == 7 else ""
        print(f"  [{r}][{c}] = {val} {marker}")

# Within this rectangle, which cells are not 7?
gaps_7 = []
for r in range(rmin, rmax+1):
    for c in range(cmin, cmax+1):
        if grid[r][c] != 7:
            gaps_7.append((r, c))

print(f"\nGaps in 7s rectangle: {gaps_7}")

# Check if any of these gaps have 0
for r, c in gaps_7:
    print(f"  ({r}, {c}): value = {grid[r][c]}")

# Also check if there's a 0 adjacent to this gap
print("\nAdjacent cells to gaps (8-directional):")
for r, c in gaps_7:
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width:
                if (nr, nc) != (r, c):
                    val = grid[nr][nc]
                    print(f"  ({nr}, {nc}): {val}")
                    if val == 0:
                        print(f"    ^^^ Found 0 at ({nr}, {nc})!")

# Let me check if scattered 0s have any 8-way connections to rectangle structures
# Or if they form their own pattern

print("All 0 positions:")
positions_0 = sorted(element_counts[0])
for (r, c) in positions_0:
    print(f"  ({r}, {c})")

# Check 8-way neighbors of each 0 to see if any are rectangle edges
print("\n\nChecking 8-way neighbors of 0s:")
for (r0, c0) in positions_0:
    neighbors = []
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r0 + dr, c0 + dc
            if 0 <= nr < height and 0 <= nc < width:
                val = grid[nr][nc]
                if val in [2, 3, 4, 5, 7, 8, 9]:  # colored elements
                    neighbors.append(((nr, nc), val))
    if neighbors:
        print(f"0 at ({r0}, {c0}) neighbors: {neighbors}")

# Let me also check if rectangles are positioned in relation to 0s
print("\n\nRectangle positions:")
rectangles = {
    "3": (21, 15, 3, 6),  # (row_start, row_end, col_start, col_end)
    "5": (22, 23, 3, 5),
    "7": (2, 4, 9, 11)
}
for name, (r1, r2, c1, c2) in rectangles.items():
    print(f"{name}-rect: rows {r1}-{r2}, cols {c1}-{c2}")

# Check if any 0 is inside or bordering these rectangles
print("\n\n0s in relation to rectangles:")
for (r0, c0) in positions_0:
    in_rect = []
    for name, (r1, r2, c1, c2) in rectangles.items():
        on_perimeter = (r0 == r1 or r0 == r2 or c0 == c1 or c0 == c2)
        inside = (r1 < r0 < r2 and c1 < c0 < c2)
        if on_perimeter or inside:
            in_rect.append((name, on_perimeter, inside))
    if in_rect:
        print(f"0 at ({r0}, {c0}) in/border: {in_rect}")

# Let me test a simple hypothesis: 
# Replace 0s that are exactly inside/on rectangles with rectangle color
# For 0s not adjacent to rectangles, leave them as 0 (or replace with 1?)

# First, let me be precise about which 0s are "inside" the rectangle border
# (within 1 cell of any rectangle cell)

print("Checking each 0's proximity to rectangles:")
for (r0, c0) in positions_0:
    nearest_rect = None
    min_dist = float('inf')
    for name, (r1, r2, c1, c2) in rectangles.items():
        # Find nearest distance to any cell in this rectangle
        min_dist_to_rect = float('inf')
        for r in range(r1, r2+1):
            for c in range(c1, c2+1):
                dist = abs(r0 - r) + abs(c0 - c)  # Manhattan
                if dist < min_dist_to_rect:
                    min_dist_to_rect = dist
        # Check if 0 is on or adjacent to rectangle
        adjacent_dist = min_dist_to_rect <= 2  # Within 2 cells
        if adjacent_dist:
            if dist < min_dist or min_dist_to_rect < min_dist:  # Simplified: adjacent
                nearest_rect = (name, min_dist_to_rect)
                break
    print(f"0 at ({r0}, {c0}): nearest rectangle = {nearest_rect}")

# Actually let me be more precise
print("\n\n=== Distant checking ===")
for (r0, c0) in positions_0:
    for name, (r1, r2, c1, c2) in rectangles.items():
        # Check if 0 is on rectangle border
        on_border = False
        if r0 == r1 and c1 <= c0 <= c2:
            on_border = True
        elif r0 == r2 and c1 <= c0 <= c2:
            on_border = True
        elif c0 == c1 and r1 <= r0 <= r2:
            on_border = True
        elif c0 == c2 and r1 <= r0 <= r2:
            on_border = True
        # Check if 0 is exactly inside rectangle (not on border)
        inside = r1 < r0 < r2 and c1 < c0 < c2

        if on_border or inside:
            print(f"0 at ({r0}, {c0}): ON/INSIDE {name}-rect (border={on_border}, inside={inside})")
            break

