    for name, (r1, r2, c1, c2) in rectangles.items():
        on_border = (r0 == r1 and c1 <= c0 <= c2) or \
                    (r0 == r2 and c1 <= c0 <= c2) or \
                    (c0 == c1 and r1 <= r0 <= r2) or \
                    (c0 == c2 and r1 <= r0 <= r2)
        inside = r1 < r0 < r2 and c1 < c0 < c2
        if on_border or inside:
            on_or_in.append((name, "border" if on_border else "inside"))

    if on_or_in:
        for name, pos in on_or_in:
            print(f"0 at ({r0}, {c0}): {name}-rect ({pos})")
    else:
        print(f"0 at ({r0}, {c0}): scattered (no rect)")

